#include <stdlib.h>
#include <string.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NCB 256

typedef float v8 __attribute__((vector_size(32)));

static inline v8 loadu(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void storeu(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b + k * NR);
        v8 b1 = *(const v8 *)(b + k * NR + 8);
        const float *ak = a + k * MR;
        float a0 = ak[0], a1 = ak[1], a2 = ak[2], a3 = ak[3], a4 = ak[4], a5 = ak[5];
        c00 += b0 * a0; c01 += b1 * a0;
        c10 += b0 * a1; c11 += b1 * a1;
        c20 += b0 * a2; c21 += b1 * a2;
        c30 += b0 * a3; c31 += b1 * a3;
        c40 += b0 * a4; c41 += b1 * a4;
        c50 += b0 * a5; c51 += b1 * a5;
    }

    v8 acc[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                     {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *ci = c + (size_t)i * ldc;
            if (first) {
                storeu(ci, acc[i][0]);
                storeu(ci + 8, acc[i][1]);
            } else {
                storeu(ci, loadu(ci) + acc[i][0]);
                storeu(ci + 8, loadu(ci + 8) + acc[i][1]);
            }
        }
    } else {
        float t[MR * NR];
        for (int i = 0; i < MR; i++) {
            memcpy(t + i * NR, &acc[i][0], sizeof(v8));
            memcpy(t + i * NR + 8, &acc[i][1], sizeof(v8));
        }
        for (int i = 0; i < mr; i++) {
            float *ci = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) ci[j] = t[i * NR + j];
            else
                for (int j = 0; j < nr; j++) ci[j] += t[i * NR + j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int np = (n + NR - 1) / NR * NR;
    float *Bp = aligned_alloc(64, sizeof(float) * (size_t)KC * np);
    int nib = (n + MC - 1) / MC;
    int njb = (n + NCB - 1) / NCB;

    #pragma omp parallel
    {
        float *Ap = aligned_alloc(64, sizeof(float) * MC * KC);

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;

            #pragma omp for schedule(static)
            for (int jp = 0; jp < np / NR; jp++) {
                float *dst = Bp + (size_t)jp * NR * kc;
                int col0 = jp * NR;
                int w = n - col0 < NR ? n - col0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + col0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < w; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }

            #pragma omp for schedule(dynamic)
            for (int t = 0; t < nib * njb; t++) {
                int ib = t / njb, jb = t % njb;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCB;
                int nc = n - jc < NCB ? n - jc : NCB;

                for (int ir = 0; ir < mc; ir += MR) {
                    float *dst = Ap + (size_t)ir * kc;
                    for (int i = 0; i < MR; i++) {
                        if (ir + i < mc) {
                            const float *src = A + (size_t)(ic + ir + i) * n + pc;
                            for (int k = 0; k < kc; k++) dst[k * MR + i] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + i] = 0.0f;
                        }
                    }
                }

                for (int jr = 0; jr < nc; jr += NR) {
                    const float *bp = Bp + (size_t)((jc + jr) / NR) * NR * kc;
                    int nr = nc - jr < NR ? nc - jr : NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(ic + ir) * n + jc + jr, n,
                               mr, nr, pc == 0);
                    }
                }
            }
        }

        free(Ap);
    }

    free(Bp);
}
